/**
 ******************************************************************************
 * @file    blight_forecast.c
 * @brief   Random Forest inference for the 24-h weather-risk forecast.
 *
 *          The forest is stored as flat const arrays in
 *          blight_forecast_model.h, generated by ml_forecast/export_c.py.
 *          Thresholds are float32 values rounded DOWN from scikit-learn's
 *          double thresholds, so "x <= thr" gives exactly the same branch as
 *          scikit-learn for every float32 input (no truncation problem as in
 *          F4). Leaves store the class-1 probability of that leaf.
 *
 *          Pure C99: no dynamic allocation, no platform headers, no I/O.
 ******************************************************************************
 */

#include "blight_forecast.h"
#include "blight_forecast_model.h"

#include <stddef.h>

/**
 * @brief  Walks one tree from its root to a leaf.
 * @param  root      Index of the tree's root node.
 * @param  features  Feature vector.
 * @return Leaf probability (0..1), or 0 if the tree data are inconsistent.
 */
static float bf_tree_leaf(uint32_t root, const float *features)
{
    uint32_t node = root;

    /* A path can never be longer than the deepest tree; the bound keeps a
     * corrupted table from looping forever. */
    for (uint32_t step = 0u; step <= BF_MODEL_MAX_DEPTH; step++)
    {
        const int32_t f = (int32_t)bf_node_feature[node];
        if (f < 0)
        {
            return bf_node_value[node];
        }
        if ((uint32_t)f >= BF_N_FEATURES)
        {
            return 0.0f;
        }
        node = (features[f] <= bf_node_value[node]) ? (uint32_t)bf_node_left[node]
                                                    : (uint32_t)bf_node_right[node];
        if (node >= BF_MODEL_N_NODES)
        {
            return 0.0f;
        }
    }
    return 0.0f;
}

/**
 * @brief  Runs the embedded Random Forest on a feature vector.
 */
bf_status_t bf_predict_proba(const float *features, float *proba)
{
    float sum = 0.0f;

    if ((features == NULL) || (proba == NULL))
    {
        return BF_ERR_NULL_ARG;
    }
    for (uint32_t t = 0u; t < BF_MODEL_N_TREES; t++)
    {
        sum += bf_tree_leaf((uint32_t)bf_tree_root[t], features);
    }
    *proba = sum / (float)BF_MODEL_N_TREES;
    return BF_OK;
}

/**
 * @brief  Features + model in one call.
 */
bf_status_t bf_forecast(const float *temp_c,
                        const float *rh_pct,
                        const uint8_t *valid,
                        uint16_t n_hours,
                        bf_result_t *result)
{
    float features[BF_N_FEATURES];
    uint8_t filled = 0u;
    bf_status_t st;

    if (result == NULL)
    {
        return BF_ERR_NULL_ARG;
    }
    result->probability = 0.0f;
    result->warning = 0u;
    result->filled_hours = 0u;

    st = bf_compute_features(temp_c, rh_pct, valid, n_hours, features, &filled);
    if (st != BF_OK)
    {
        return st;
    }
    st = bf_predict_proba(features, &result->probability);
    if (st != BF_OK)
    {
        return st;
    }
    result->filled_hours = filled;
    result->warning = (result->probability >= BF_MODEL_THRESHOLD) ? 1u : 0u;
    return BF_OK;
}

/** @brief Warning threshold chosen on the validation years. */
float bf_warning_threshold(void)
{
    return BF_MODEL_THRESHOLD;
}

/** @brief Model identifier string. */
const char *bf_model_id(void)
{
    return BF_MODEL_ID;
}
